import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { FitnessClassTable } from '@/components/classes/FitnessClassTable';
import { FitnessClassForm } from '@/components/classes/FitnessClassForm';
import { DeleteConfirmationDialog } from '@/components/shared/DeleteConfirmationDialog';
import { useAdminGetAllFitnessClasses, useCreateFitnessClass, useUpdateFitnessClass, useDeleteFitnessClass, useFitnessClassById } from '@/hooks/fitnessClassHooks';
import { FitnessClassDto } from '@/types/fitnessClass';
import { toast } from 'sonner';
import { Skeleton } from '@/components/ui/skeleton';

export default function AdminClassesPage() {
  const { data: classes, isLoading, isError, error } = useAdminGetAllFitnessClasses();
  const { mutate: createClass } = useCreateFitnessClass();
  const { mutate: updateClass } = useUpdateFitnessClass();
  const { mutate: deleteClass } = useDeleteFitnessClass();
  const { data: editingClass, isLoading: isLoadingEditingClass } = useFitnessClassById(editingClassId || '');

  const [isFormOpen, setIsFormOpen] = useState<boolean>(false);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState<boolean>(false);
  const [editingClassId, setEditingClassId] = useState<string | null>(null);
  const [deletingClassId, setDeletingClassId] = useState<string | null>(null);

  const handleCreateClass = (data: FitnessClassDto): void => {
    createClass(data, {
      onSuccess: () => {
        toast.success('Fitness class created successfully.');
        setIsFormOpen(false);
        setEditingClassId(null);
      },
      onError: (err) => {
        toast.error(`Failed to create fitness class: ${err.message}`);
      },
    });
  };

  const handleEditClass = (data: FitnessClassDto): void => {
    if (editingClassId) {
      updateClass({ id: editingClassId, request: data }, {
        onSuccess: () => {
          toast.success('Fitness class updated successfully.');
          setIsFormOpen(false);
          setEditingClassId(null);
        },
        onError: (err) => {
          toast.error(`Failed to update fitness class: ${err.message}`);
        },
      });
    }
  };

  const handleDeleteClass = (): void => {
    if (deletingClassId) {
      deleteClass(deletingClassId, {
        onSuccess: () => {
          toast.success('Fitness class deleted successfully.');
          setIsDeleteDialogOpen(false);
          setDeletingClassId(null);
        },
        onError: (err) => {
          toast.error(`Failed to delete fitness class: ${err.message}`);
        },
      });
    }
  };

  const onEdit = (fitnessClass: FitnessClassDto): void => {
    setEditingClassId(String(fitnessClass.id));
    setIsFormOpen(true);
  };

  const onDelete = (id: string): void => {
    setDeletingClassId(id);
    setIsDeleteDialogOpen(true);
  };

  if (isLoading) {
    return (
      <AdminLayout>
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-3xl font-bold">Manage Fitness Classes</h1>
          <Skeleton className="h-10 w-32" />
        </div>
        <Skeleton className="h-[500px] w-full" />
      </AdminLayout>
    );
  }

  if (isError) {
    return (
      <AdminLayout>
        <div className="text-red-500">Error loading fitness classes: {error?.message}</div>
      </AdminLayout>
    );
  }

  return (
    <AdminLayout>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold">Manage Fitness Classes</h1>
        <Dialog open={isFormOpen} onOpenChange={setIsFormOpen}>
          <DialogTrigger asChild>
            <Button onClick={() => { setEditingClassId(null); setIsFormOpen(true); }} data-testid="add-class-button">
              Add New Class
            </Button>
          </DialogTrigger>
          <DialogContent className="sm:max-w-[600px]">
            <DialogHeader>
              <DialogTitle>{editingClassId ? 'Edit Fitness Class' : 'Create New Fitness Class'}</DialogTitle>
            </DialogHeader>
            {isLoadingEditingClass && editingClassId ? (
              <Skeleton className="h-[400px] w-full" />
            ) : (
              <FitnessClassForm
                initialData={editingClassId ? editingClass : undefined}
                onSubmit={editingClassId ? handleEditClass : handleCreateClass}
              />
            )}
          </DialogContent>
        </Dialog>
      </div>

      <FitnessClassTable classes={classes || []} onEdit={onEdit} onDelete={onDelete} />

      <DeleteConfirmationDialog
        isOpen={isDeleteDialogOpen}
        onClose={() => setIsDeleteDialogOpen(false)}
        onConfirm={handleDeleteClass}
        title="Confirm Deletion"
        description="Are you sure you want to delete this fitness class? This action cannot be undone."
      />
    </AdminLayout>
  );
}

import { useState } from 'react';
import { AdminLayout } from '@/components/AdminLayout';
import { BookingTable } from '@/components/bookings/BookingTable';
import { DeleteConfirmationDialog } from '@/components/shared/DeleteConfirmationDialog';
import { useBookings, useAdminCancelBooking } from '@/hooks/bookingHooks';
import { Button } from '@/components/ui/button';
import { Loader2 } from 'lucide-react';
import { toast } from 'sonner';

export default function AdminBookingsPage() {
  const { data: bookings, isLoading, isError, error } = useBookings();
  const { mutate: cancelBooking, isPending: isCancelling } = useAdminCancelBooking();

  const [isCancelDialogOpen, setIsCancelDialogOpen] = useState<boolean>(false);
  const [selectedBookingId, setSelectedBookingId] = useState<string | null>(null);

  const handleCancelClick = (bookingId: string): void => {
    setSelectedBookingId(bookingId);
    setIsCancelDialogOpen(true);
  };

  const handleConfirmCancel = (): void => {
    if (selectedBookingId) {
      cancelBooking(selectedBookingId, {
        onSuccess: () => {
          toast.success('Booking cancelled successfully.');
          setIsCancelDialogOpen(false);
          setSelectedBookingId(null);
        },
        onError: (err) => {
          toast.error(`Failed to cancel booking: ${err.message}`);
        },
      });
    }
  };

  const handleCloseCancelDialog = (): void => {
    setIsCancelDialogOpen(false);
    setSelectedBookingId(null);
  };

  if (isLoading) {
    return (
      <AdminLayout>
        <div className="flex justify-center items-center h-64">
          <Loader2 className="h-8 w-8 animate-spin" />
        </div>
      </AdminLayout>
    );
  }

  if (isError) {
    return (
      <AdminLayout>
        <div className="text-center text-red-500">
          Error loading bookings: {error?.message}
        </div>
      </AdminLayout>
    );
  }

  return (
    <AdminLayout>
      <section className="py-8 px-4">
        <div className="max-w-7xl mx-auto">
          <h1 className="text-3xl font-bold text-gray-900 mb-6">Manage Bookings</h1>
          {bookings && bookings.length > 0 ? (
            <BookingTable bookings={bookings} onCancel={handleCancelClick} />
          ) : (
            <div className="text-center py-8">
              <p className="text-gray-600">No bookings found.</p>
            </div>
          )}
        </div>
      </section>

      <DeleteConfirmationDialog
        isOpen={isCancelDialogOpen}
        onClose={handleCloseCancelDialog}
        onConfirm={handleConfirmCancel}
        title="Cancel Booking"
        description="Are you sure you want to cancel this booking? This action cannot be undone."
      />
    </AdminLayout>
  );
}

import { useState } from 'react';
import { AdminLayout } from '@/components/AdminLayout';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { TrainerTable } from '@/components/trainers/TrainerTable';
import { TrainerForm } from '@/components/trainers/TrainerForm';
import { DeleteConfirmationDialog } from '@/components/shared/DeleteConfirmationDialog';
import { useAdminGetAllTrainers, useCreateTrainer, useUpdateTrainer, useDeleteTrainer } from '@/hooks/trainerHooks';
import { TrainerDto } from '@/types/trainer';
import { toast } from 'sonner';
import { Skeleton } from '@/components/ui/skeleton';

export default function AdminTrainersPage() {
  const { data: trainers, isLoading, isError, error } = useAdminGetAllTrainers();
  const { mutate: createTrainer } = useCreateTrainer();
  const { mutate: updateTrainer } = useUpdateTrainer();
  const { mutate: deleteTrainer } = useDeleteTrainer();

  const [isFormOpen, setIsFormOpen] = useState<boolean>(false);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState<boolean>(false);
  const [selectedTrainer, setSelectedTrainer] = useState<TrainerDto | null>(null);
  const [trainerToDeleteId, setTrainerToDeleteId] = useState<string | null>(null);

  const handleCreateTrainer = (data: TrainerDto): void => {
    createTrainer(data, {
      onSuccess: () => {
        toast.success('Trainer created successfully.');
        setIsFormOpen(false);
        setSelectedTrainer(null);
      },
      onError: (err) => {
        toast.error(`Failed to create trainer: ${err.message}`);
      },
    });
  };

  const handleEditTrainer = (trainer: TrainerDto): void => {
    setSelectedTrainer(trainer);
    setIsFormOpen(true);
  };

  const handleUpdateTrainer = (data: TrainerDto): void => {
    if (selectedTrainer) {
      updateTrainer(
        { id: selectedTrainer.id.toString(), request: data },
        {
          onSuccess: () => {
            toast.success('Trainer updated successfully.');
            setIsFormOpen(false);
            setSelectedTrainer(null);
          },
          onError: (err) => {
            toast.error(`Failed to update trainer: ${err.message}`);
          },
        },
      );
    }
  };

  const handleDeleteTrainer = (id: string): void => {
    setTrainerToDeleteId(id);
    setIsDeleteDialogOpen(true);
  };

  const confirmDeleteTrainer = (): void => {
    if (trainerToDeleteId) {
      deleteTrainer(trainerToDeleteId, {
        onSuccess: () => {
          toast.success('Trainer deleted successfully.');
          setIsDeleteDialogOpen(false);
          setTrainerToDeleteId(null);
        },
        onError: (err) => {
          toast.error(`Failed to delete trainer: ${err.message}`);
        },
      });
    }
  };

  if (isLoading) {
    return (
      <AdminLayout>
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-3xl font-bold">Manage Trainers</h1>
          <Skeleton className="w-32 h-10" />
        </div>
        <Skeleton className="h-[500px] w-full" />
      </AdminLayout>
    );
  }

  if (isError) {
    return (
      <AdminLayout>
        <div className="text-red-500">Error loading trainers: {error?.message}</div>
      </AdminLayout>
    );
  }

  return (
    <AdminLayout>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold">Manage Trainers</h1>
        <Dialog open={isFormOpen} onOpenChange={setIsFormOpen}>
          <DialogTrigger asChild>
            <Button onClick={() => setSelectedTrainer(null)} data-testid="add-trainer-cta">Add New Trainer</Button>
          </DialogTrigger>
          <DialogContent className="sm:max-w-[600px]">
            <DialogHeader>
              <DialogTitle>{selectedTrainer ? 'Edit Trainer' : 'Create New Trainer'}</DialogTitle>
            </DialogHeader>
            <TrainerForm
              initialData={selectedTrainer || undefined}
              onSubmit={selectedTrainer ? handleUpdateTrainer : handleCreateTrainer}
            />
          </DialogContent>
        </Dialog>
      </div>

      <TrainerTable trainers={trainers || []} onEdit={handleEditTrainer} onDelete={handleDeleteTrainer} />

      <DeleteConfirmationDialog
        isOpen={isDeleteDialogOpen}
        onClose={() => setIsDeleteDialogOpen(false)}
        onConfirm={confirmDeleteTrainer}
        title="Confirm Delete"
        description="Are you sure you want to delete this trainer? This action cannot be undone."
      />
    </AdminLayout>
  );
}

import { useState } from 'react';
import { AdminLayout } from '@/components/AdminLayout';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { ReviewTable } from '@/components/reviews/ReviewTable';
import { ReviewForm } from '@/components/reviews/ReviewForm';
import { DeleteConfirmationDialog } from '@/components/shared/DeleteConfirmationDialog';
import { useReviews, useCreateReview, useUpdateReview, useDeleteReview, useApproveReview } from '@/hooks/reviewHooks';
import { ReviewDto } from '@/types/review';
import { toast } from 'sonner';
import { Skeleton } from '@/components/ui/skeleton';

const AdminReviewsPage = () => {
  const { data: reviews, isLoading, isError, error } = useReviews();
  const createReviewMutation = useCreateReview();
  const updateReviewMutation = useUpdateReview();
  const deleteReviewMutation = useDeleteReview();
  const approveReviewMutation = useApproveReview();

  const [isFormOpen, setIsFormOpen] = useState<boolean>(false);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState<boolean>(false);
  const [editingReview, setEditingReview] = useState<ReviewDto | undefined>(undefined);
  const [reviewToDelete, setReviewToDelete] = useState<number | null>(null);

  const handleAddReview = () => {
    setEditingReview(undefined);
    setIsFormOpen(true);
  };

  const handleEditReview = (review: ReviewDto) => {
    setEditingReview(review);
    setIsFormOpen(true);
  };

  const handleDeleteReview = (id: number) => {
    setReviewToDelete(id);
    setIsDeleteDialogOpen(true);
  };

  const handleApproveReview = async (id: number) => {
    try {
      await approveReviewMutation.mutateAsync(id);
      toast.success('Review approved successfully!');
    } catch (error) {
      toast.error('Failed to approve review.');
      console.error('Failed to approve review:', error);
    }
  };

  const confirmDelete = async () => {
    if (reviewToDelete !== null) {
      try {
        await deleteReviewMutation.mutateAsync(reviewToDelete);
        toast.success('Review deleted successfully!');
        setIsDeleteDialogOpen(false);
        setReviewToDelete(null);
      } catch (error) {
        toast.error('Failed to delete review.');
        console.error('Failed to delete review:', error);
      }
    }
  };

  const handleSubmit = async (data: ReviewDto) => {
    try {
      if (editingReview) {
        await updateReviewMutation.mutateAsync({ id: editingReview.id, request: data });
        toast.success('Review updated successfully!');
      } else {
        await createReviewMutation.mutateAsync(data);
        toast.success('Review created successfully!');
      }
      setIsFormOpen(false);
      setEditingReview(undefined);
    } catch (error) {
      toast.error(`Failed to ${editingReview ? 'update' : 'create'} review.`);
      console.error(`Failed to ${editingReview ? 'update' : 'create'} review:`, error);
    }
  };

  if (isLoading) {
    return (
      <AdminLayout>
        <div className="container mx-auto py-8">
          <h1 className="text-3xl font-bold mb-6">Manage Reviews</h1>
          <Skeleton className="h-10 w-32 mb-4" />
          <Skeleton className="h-[500px] w-full" />
        </div>
      </AdminLayout>
    );
  }

  if (isError) {
    return (
      <AdminLayout>
        <div className="container mx-auto py-8">
          <h1 className="text-3xl font-bold mb-6">Manage Reviews</h1>
          <p className="text-red-500">Error loading reviews: {error?.message}</p>
        </div>
      </AdminLayout>
    );
  }

  return (
    <AdminLayout>
      <div className="container mx-auto py-8">
        <h1 className="text-3xl font-bold mb-6">Manage Reviews</h1>
        <div className="flex justify-end mb-4">
          <Button onClick={handleAddReview} data-testid="add-review-button">Add New Review</Button>
        </div>
        <ReviewTable
          reviews={reviews || []}
          onEdit={handleEditReview}
          onDelete={handleDeleteReview}
          onApprove={handleApproveReview}
        />

        <Dialog open={isFormOpen} onOpenChange={setIsFormOpen}>
          <DialogContent className="sm:max-w-[425px]">
            <DialogHeader>
              <DialogTitle>{editingReview ? 'Edit Review' : 'Create New Review'}</DialogTitle>
            </DialogHeader>
            <ReviewForm initialData={editingReview} onSubmit={handleSubmit} />
          </DialogContent>
        </Dialog>

        <DeleteConfirmationDialog
          isOpen={isDeleteDialogOpen}
          onClose={() => setIsDeleteDialogOpen(false)}
          onConfirm={confirmDelete}
          title="Confirm Delete"
          description="Are you sure you want to delete this review? This action cannot be undone."
        />
      </div>
    </AdminLayout>
  );
};

export default AdminReviewsPage;

import { useState } from 'react';
import { AdminLayout } from '@/components/AdminLayout';
import { EnquiryTable } from '@/components/enquiries/EnquiryTable';
import { useEnquiries, useEnquiryById } from '@/hooks/enquiryHooks';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Skeleton } from '@/components/ui/skeleton';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';

export default function AdminEnquiriesPage() {
  const { data: enquiries, isLoading, isError, error } = useEnquiries();
  const [isDetailsModalOpen, setIsDetailsModalOpen] = useState<boolean>(false);
  const [selectedEnquiryId, setSelectedEnquiryId] = useState<number | null>(null);

  const { data: selectedEnquiry, isLoading: isLoadingSelectedEnquiry } = useEnquiryById(
    selectedEnquiryId ? String(selectedEnquiryId) : ''
  );

  const handleViewDetails = (id: number): void => {
    setSelectedEnquiryId(id);
    setIsDetailsModalOpen(true);
  };

  const handleCloseDetailsModal = (): void => {
    setIsDetailsModalOpen(false);
    setSelectedEnquiryId(null);
  };

  if (isLoading) {
    return (
      <AdminLayout>
        <div className="space-y-4">
          <Skeleton className="h-10 w-48" />
          <Skeleton className="h-[300px] w-full" />
        </div>
      </AdminLayout>
    );
  }

  if (isError) {
    return (
      <AdminLayout>
        <div className="text-red-500">Error: {error?.message || 'Failed to load enquiries.'}</div>
      </AdminLayout>
    );
  }

  return (
    <AdminLayout>
      <section className="py-8 px-4">
        <div className="max-w-7xl mx-auto">
          <h1 className="text-3xl font-bold text-[#1A1A1A] mb-6">Manage Enquiries</h1>
          {enquiries && enquiries.length > 0 ? (
            <EnquiryTable enquiries={enquiries} onViewDetails={handleViewDetails} />
          ) : (
            <div className="text-center py-10">
              <p className="text-gray-600">No enquiries found.</p>
            </div>
          )}
        </div>
      </section>

      <Dialog open={isDetailsModalOpen} onOpenChange={setIsDetailsModalOpen}>
        <DialogContent className="sm:max-w-[425px]">
          <DialogHeader>
            <DialogTitle>Enquiry Details</DialogTitle>
            <DialogDescription>
              View the full details of the selected enquiry.
            </DialogDescription>
          </DialogHeader>
          {isLoadingSelectedEnquiry ? (
            <div className="space-y-4 py-4">
              <Skeleton className="h-4 w-3/4" />
              <Skeleton className="h-4 w-1/2" />
              <Skeleton className="h-4 w-full" />
              <Skeleton className="h-20 w-full" />
            </div>
          ) : selectedEnquiry ? (
            <div className="grid gap-4 py-4">
              <div className="grid grid-cols-4 items-center gap-4">
                <Label htmlFor="name" className="text-right">
                  Name
                </Label>
                <Input id="name" value={selectedEnquiry.name} readOnly className="col-span-3" />
              </div>
              <div className="grid grid-cols-4 items-center gap-4">
                <Label htmlFor="email" className="text-right">
                  Email
                </Label>
                <Input id="email" value={selectedEnquiry.email} readOnly className="col-span-3" />
              </div>
              <div className="grid grid-cols-4 items-center gap-4">
                <Label htmlFor="phone" className="text-right">
                  Phone
                </Label>
                <Input id="phone" value={selectedEnquiry.phone} readOnly className="col-span-3" />
              </div>
              <div className="grid grid-cols-4 items-center gap-4">
                <Label htmlFor="message" className="text-right">
                  Message
                </Label>
                <Textarea id="message" value={selectedEnquiry.message} readOnly className="col-span-3 h-24" />
              </div>
              <div className="grid grid-cols-4 items-center gap-4">
                <Label htmlFor="createdAt" className="text-right">
                  Submitted At
                </Label>
                <Input id="createdAt" value={new Date(selectedEnquiry.createdAt).toLocaleString()} readOnly className="col-span-3" />
              </div>
            </div>
          ) : (
            <div className="text-center py-4 text-gray-600">Enquiry details not found.</div>
          )}
          <div className="flex justify-end">
            <Button onClick={handleCloseDetailsModal}>Close</Button>
          </div>
        </DialogContent>
      </Dialog>
    </AdminLayout>
  );
}

import { useNavigate } from 'react-router-dom';
import { useMembershipPlans } from '@/hooks/membershipHooks';
import { useCart } from '@/cart/CartContext';
import { MembershipPlanCard } from '@/components/membership/MembershipPlanCard';
import { Button } from '@/components/ui/button';
import { Skeleton } from '@/components/ui/skeleton';
import { ROUTES } from '@/routes';
import type { MembershipPlan } from '@/types/membership';

export default function MembershipPage() {
  const { data: membershipPlans, isLoading, isError } = useMembershipPlans();
  const { addItem } = useCart();
  const navigate = useNavigate();

  const handleSelectPlan = (plan: MembershipPlan): void => {
    addItem({
      id: plan.id,
      name: plan.name,
      unitPrice: plan.price,
      imageUrl: null, // Membership plans don't typically have images
      variantKey: `membership-${plan.id}`,
      metadata: { durationInMonths: plan.durationInMonths },
    });
    navigate(ROUTES.CHECKOUT);
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-white">
        <section className="relative h-[500px] md:h-[600px] bg-cover bg-center flex items-center justify-center" style={{ backgroundImage: 'url(/images/hero-membership.webp)' }}>
          <div className="absolute inset-0 bg-black bg-opacity-50" />
          <div className="relative z-10 text-center text-white p-4">
            <Skeleton className="h-12 w-96 mx-auto mb-4" />
            <Skeleton className="h-8 w-80 mx-auto" />
          </div>
        </section>
        <section className="py-16 px-4 bg-[#F5F5F5]">
          <div className="max-w-7xl mx-auto">
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
              {[1, 2, 3].map((i) => (
                <CardSkeleton key={i} />
              ))}
            </div>
          </div>
        </section>
      </div>
    );
  }

  if (isError) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-white">
        <p className="text-red-600 text-lg">Error loading membership plans.</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white">
      <section
        className="relative h-[500px] md:h-[600px] bg-cover bg-center flex items-center justify-center"
        style={{ backgroundImage: 'url(/images/hero-membership.webp)' }}
      >
        <div className="absolute inset-0 bg-black bg-opacity-50" />
        <div className="relative z-10 text-center text-white p-4">
          <h1 className="text-4xl md:text-6xl font-bold mb-4" data-testid="membership-hero-title">
            Unlock Your Potential with ABS FITNESS Memberships
          </h1>
          <p className="text-lg md:text-xl" data-testid="membership-hero-subtitle">
            Choose the plan that fits your fitness journey.
          </p>
        </div>
      </section>

      <section className="py-16 px-4 bg-[#F5F5F5]">
        <div className="max-w-7xl mx-auto">
          <h2 className="text-2xl md:text-3xl font-semibold text-center mb-12 text-[#1A1A1A]">Our Membership Plans</h2>
          {membershipPlans && membershipPlans.length > 0 ? (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
              {membershipPlans.map((plan) => (
                <MembershipPlanCard key={plan.id} plan={plan} onSelectPlan={handleSelectPlan} />
              ))}
            </div>
          ) : (
            <div className="text-center text-gray-600 text-lg">No membership plans available at the moment.</div>
          )}
        </div>
      </section>
    </div>
  );
}

function CardSkeleton(): React.JSX.Element {
  return (
    <div className="bg-white rounded-xl shadow-md border border-gray-100 p-6">
      <Skeleton className="h-8 w-3/4 mb-4" />
